import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {

  const scannerRef = useRef(null);
  const lastScanRef = useRef(null);

  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");

  const playSound = () => {
    const audio = new Audio("/success.mp3");
    audio.play();
  };

  useEffect(() => {

    const startScanner = async () => {

      const scanner = new Html5Qrcode("reader");

      scannerRef.current = scanner;

      try {

        await scanner.start(
          { facingMode: "environment" },

          {
            fps: 15,
            qrbox: { width: 220, height: 220 }
          },

          async (decodedText) => {

            console.log("QR DETECTED:", decodedText);

            if (lastScanRef.current === decodedText) return;

            lastScanRef.current = decodedText;

            try {

              const userId = decodedText;

              /* VERIFY USER */

              const verifyRes = await fetch(
                `http://localhost:5000/verify-user/${userId}`
              );

              const verifyData = await verifyRes.json();

              if (!verifyData.success) {

                setStatus("notfound");
                setStudent(null);

                setTimeout(() => {
                  lastScanRef.current = null;
                }, 2000);

                return;
              }

              setStudent(verifyData.user);

              /* MARK ATTENDANCE */

              const attendanceRes = await fetch(
                `http://localhost:5000/mark-attendance/${userId}`,
                {
                  method: "PUT"
                }
              );

              const attendanceData = await attendanceRes.json();

              if (attendanceData.success) {

                setStatus("success");
                playSound();

              } else {

                setStatus("already");

              }

            } catch (error) {

              console.log("Scanner error:", error);
              setStatus("servererror");

            }

            setTimeout(() => {
              lastScanRef.current = null;
            }, 2000);

          },

          (error) => {
            // ignore scanning errors
          }
        );

      } catch (err) {

        console.log("Camera start error:", err);

      }

    };

    startScanner();

    return () => {

      if (scannerRef.current) {

        scannerRef.current.stop()
          .then(() => scannerRef.current.clear())
          .catch((err) => console.log(err));

      }

    };

  }, []);

  return (

    <div style={{ textAlign: "center", marginTop: "30px" }}>

      <h2>QR Attendance Scanner</h2>

      <div
        id="reader"
        style={{
          width: "300px",
          height: "300px",
          margin: "auto"
        }}
      ></div>

      {student && (

        <div
          style={{
            width: "320px",
            margin: "20px auto",
            padding: "20px",
            borderRadius: "10px",
            background: "#f5f5f5"
          }}
        >

          {student.photo && (

            <img
              src={`http://localhost:5000/${student.photo}`}
              alt="student"
              width="100"
              style={{ borderRadius: "50%" }}
            />

          )}

          <h3>{student.name}</h3>

          <p>{student.college_name}</p>

          {status === "success" && (
            <h2 style={{ color: "green" }}>✔ Attendance Marked</h2>
          )}

          {status === "already" && (
            <h2 style={{ color: "red" }}>❌ Already Scanned</h2>
          )}

          {status === "notfound" && (
            <h2 style={{ color: "orange" }}>User Not Found</h2>
          )}

          {status === "servererror" && (
            <h2 style={{ color: "red" }}>Server Error</h2>
          )}

        </div>

      )}

    </div>

  );

}

export default QRScanner;
